import { cn, normalizeTone } from '@cascivo/core/pure'
import type { ToneInput } from '@cascivo/core'
import type { HTMLAttributes } from 'react'
import styles from './badge.module.css'

/**
 * Badge-only looks that aren't a severity tone.
 *
 * Named for the PROP it types, not for a prop that does not exist. As `BadgeShape` it sat
 * directly above `BadgeProps` in the generated `.d.ts` and read as the type of a `shape`
 * prop, so an adopter wrote `<Badge shape="outline">` in four files before the compiler
 * disagreed (2026-08-08 report A). A type named after a prop the component does not have is
 * a trap of our own making.
 */
type BadgeVariant = 'secondary' | 'outline' | 'primary'

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Severity tone or badge-specific look. Accepts the catalog-wide `Tone` vocabulary
   * (`neutral | info | success | warning | danger`) as well as Badge's historical spellings
   * (`default`, `destructive`, `error`) — they are aliases of the same tones, so one domain
   * enum can drive `Badge`, `Tag`, `Status` and `Notification` with no lookup table.
   */
  variant?: ToneInput | BadgeVariant
  size?: 'sm' | 'md'
}

/**
 * Canonical tone → the value Badge's stylesheet keys on.
 *
 * `neutral` maps to the SUBTLE look, not the accent one. It used to map to `default`
 * (`--cascivo-color-accent`), which made Badge the only one of the four tone-taking
 * components to render "neutral" as the brand colour — every framework label, preview-env
 * tag and member role in a reported dashboard came out as a primary-blue pill, with no
 * error and no warning. `Tag`, `Status` and `Notification` all render neutral quietly.
 * The accent look is still reachable, explicitly, as `variant="primary"`.
 */
const TONE_CLASS: Record<string, string> = {
  neutral: 'secondary',
  info: 'info',
  success: 'success',
  warning: 'warning',
  danger: 'destructive',
}

export function Badge({
  variant = 'default',
  size = 'md',
  className,
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      data-variant={TONE_CLASS[normalizeTone(variant)] ?? variant}
      data-size={size}
      className={cn(styles['badge'], className)}
      {...props}
    >
      {children}
    </span>
  )
}

@layer cascivo.component {
  .badge {
    display: inline-flex;
    align-items: center;
    font-family: var(--cascivo-font-sans);
    font-weight: var(--cascivo-font-medium);
    border-radius: var(--cascivo-radius-badge);
    border: 1px solid transparent;
    white-space: nowrap;

    &[data-size='sm'] {
      padding-inline: var(--cascivo-space-2);
      padding-block: var(--cascivo-space-1);
      font-size: var(--cascivo-text-xs);
      line-height: 1;
    }

    &[data-size='md'] {
      padding-inline: var(--cascivo-space-3);
      padding-block: var(--cascivo-space-1);
      font-size: var(--cascivo-text-xs);
      line-height: var(--cascivo-leading-normal);
    }

    &[data-variant='default'] {
      background-color: var(--cascivo-color-accent);
      color: var(--cascivo-color-text-on-accent);
    }

    &[data-variant='secondary'] {
      background-color: var(--cascivo-color-bg-subtle);
      color: var(--cascivo-color-text);
      border-color: var(--cascivo-color-border);
    }

    &[data-variant='success'] {
      background-color: var(--cascivo-color-success-subtle);
      color: var(--cascivo-color-success-foreground);
    }

    &[data-variant='warning'] {
      background-color: var(--cascivo-color-warning-subtle);
      color: var(--cascivo-color-warning-foreground);
    }

    &[data-variant='destructive'] {
      background-color: var(--cascivo-color-destructive-subtle);
      color: var(--cascivo-color-destructive-foreground);
    }

    &[data-variant='primary'] {
      background-color: var(--cascivo-color-primary);
      color: var(--cascivo-color-primary-content);
    }

    &[data-variant='info'] {
      background-color: var(--cascivo-color-info);
      color: var(--cascivo-color-info-content);
    }

    &[data-variant='error'] {
      background-color: var(--cascivo-color-error);
      color: var(--cascivo-color-error-content);
    }

    &[data-variant='outline'] {
      background-color: transparent;
      color: var(--cascivo-color-text);
      border-color: var(--cascivo-color-border-strong);
    }
  }
}

@media (forced-colors: active) {
  .badge {
    border: 1px solid CanvasText;
    color: CanvasText;
  }
}

@media (prefers-contrast: more) {
  .badge {
    border-width: 2px;
  }
}
